fn sgn(v: i32) -> i32 {
    if v > 0 { return 1; }
    if v < 0 { return -1; }
    0
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 5 {
            host::display::state_set(8 + i * 4, (100 + i * 60) * 8);
            host::display::state_set(9 + i * 4, (120 + (i % 3) * 90) * 8);
            i = i + 1;
        }
    }
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let hot: bool = host::display::pointer_down() == 1;
    host::display::clear(0x101418);
    let mut scared: i32 = 0;
    let mut i: i32 = 0;
    while i < 5 {
        let b: i32 = 8 + i * 4;
        let mut x: i32 = host::display::state_get(b);
        let mut y: i32 = host::display::state_get(b + 1);
        let mut vx: i32 = host::display::state_get(b + 2);
        let mut vy: i32 = host::display::state_get(b + 3);
        let dx: i32 = x / 8 - px;
        let dy: i32 = y / 8 - py;
        let d2: i32 = dx * dx + dy * dy;
        if hot && d2 < 14400 {
            vx = vx + sgn(dx) * 6;
            vy = vy + sgn(dy) * 6;
            scared = scared + 1;
        } else {
            vx = vx + (w * 4 - x) / 128;
            vy = vy + (h * 4 - y) / 128;
        }
        vx = vx * 7 / 8;
        vy = vy * 7 / 8;
        x = x + vx;
        y = y + vy;
        if x < 80 { x = 80; }
        if x > (w - 10) * 8 { x = (w - 10) * 8; }
        if y < 80 { y = 80; }
        if y > (h - 10) * 8 { y = (h - 10) * 8; }
        host::display::state_set(b, x);
        host::display::state_set(b + 1, y);
        host::display::state_set(b + 2, vx);
        host::display::state_set(b + 3, vy);
        host::display::fill_rect(x / 8 - 5, y / 8 - 5, 10, 10, 0xe0e0d0);
        i = i + 1;
    }
    if hot {
        host::display::fill_rect(px - 5, py - 5, 10, 10, 0xff3030);
    }
    host::display::draw_string(8, 8, "SCARED", 0x808080, 1);
    host::display::draw_number(70, 8, scared, 0xff5050, 1);
    host::display::present();
}
